// Reescrito para suportar múltiplos adquirentes e múltiplos bancos PIX por submissão.
// Rótulos e estrutura de campos confirmados por inspeção direta do formulário Tally ao vivo (form MeW5YY).
// CORRIGIDO: rótulos reais divergiam do que este código assumia (ver notas abaixo em cada ponto).

const submissions = $('Buscar Submissões do Tally').first().json.submissions || [];
const processadas = new Set(
  $('Buscar Log de Submissões Já Processadas').all().map(item => item.json.submission_id)
);
// COMPAT 21/09/2026 (aditivo): a API do Tally devolve responses[] como { questionId, answer } e a lista questions[] com { id, title }.
// O restante deste codigo le r.value / r.field.title / r.label; o shim abaixo preenche esses campos sem alterar a logica existente.
const questoesTally = $('Buscar Submissões do Tally').first().json.questions || [];
const tituloPorQuestao = Object.fromEntries(questoesTally.map(q => [q.id, q.title]));
const novas = submissions.filter(s => !processadas.has(s.id)).map(s => ({
  ...s,
  responses: (s.responses || s.answers || []).map(r => ({
    ...r,
    value: r.value !== undefined ? r.value : r.answer,
    field: r.field || { id: r.questionId, title: tituloPorQuestao[r.questionId] },
    label: r.label || tituloPorQuestao[r.questionId],
  })),
}));

function campo(resp, label) {
  const candidatos = resp.filter(r => (r.field?.title || r.label) === label);
  const comValor = candidatos.find(r => r.value !== undefined && r.value !== null && r.value !== '');
  if (comValor) return comValor.value;
  return candidatos.length ? (candidatos[0].value ?? '') : '';
}
function campoArray(resp, label) {
  const f = resp.find(r => (r.field?.title || r.label) === label);
  const v = f ? f.value : [];
  return Array.isArray(v) ? v : (v ? [v] : []);
}
// Client ID/Client Secret/Chave EVP existem como 3 blocos SEPARADOS no formulário real
// (Sicredi, Sicoob, Cielo), todos com o MESMO título literal "Client ID" etc — não dá para
// distinguir por rótulo quando mais de um banco é selecionado na mesma submissão.
// Usa o id único da pergunta (confirmado via API real do Tally) e cai para o rótulo se o id não bater.
function campoPorId(resp, id, labelFallback) {
  const f = resp.find(r => r.questionId === id || r.field?.id === id);
  if (f) return f.value ?? '';
  return campo(resp, labelFallback);
}

// Tabela de referência: quais campos existem por adquirente (true = tem o campo)
// Rótulo do campo de afiliação é "Número de Afiliação (X)" para todos, EXCETO Sipag,
// que usa "Número do Comércio (Sipag)", e EXCETO Cielo, cujo campo vem sem sufixo
// (primeira ocorrência do bloco no formulário, sem "(Cielo)" no título real).
const TABELA_ADQUIRENTE = {
  'Cielo':                      { afiliacao: true,  logico: true  },
  'Getnet':                     { afiliacao: true,  logico: true  },
  'Safra':                      { afiliacao: true,  logico: true  },
  'Vero':                       { afiliacao: false, logico: true  },
  'Banrisul':                   { afiliacao: false, logico: true  },
  'Pagseguro':                  { afiliacao: true,  logico: false },
  'Rede':                       { afiliacao: false, logico: true  },
  'Stone':                      { afiliacao: true,  logico: true  },
  'Bin (Sicredi e Azulzinha)':  { afiliacao: true,  logico: true  },
  'Global Payments':            { afiliacao: true,  logico: false },
  'Ticket Log':                 { afiliacao: true,  logico: false },
  'CTF':                        { afiliacao: true,  logico: false },
  'Credishop':                  { afiliacao: true,  logico: false },
  'Banesecard':                 { afiliacao: true,  logico: true  },
  'Sipag':                      { afiliacao: true,  logico: true, rotuloAfiliacao: 'Número do Comércio' },
  'Mercado Pago':               { afiliacao: false, logico: false, confirmacaoPortal: true },
  'DMCard':                     { afiliacao: true,  logico: false },
  'Conductor / Dock':           { afiliacao: true,  logico: false },
};

// Estrutura de campos por banco PIX. Client ID/Secret/EVP identificados por id (ver campoPorId).
const ESTRUTURA_PIX = {
  'C6 Bank':  { campos: [] }, // fast path, sem dado técnico
  'Sicredi':  { campos: ['client_id', 'client_secret', 'tipo_chave', 'chave_pix'], ids: { client_id: 'PXad55', client_secret: 'Yz4BR5' } },
  'Sicoob':   { campos: ['client_id', 'tipo_chave', 'chave_pix'], ids: { client_id: 'NJedjj' } },
  'Cielo':    { campos: ['client_id', 'client_secret', 'chave_evp'], ids: { client_id: 'DJl9GZ', client_secret: 'l7PXEv', chave_evp: 'RJ719j' } },
  'Bradesco': { campos: [] }, // cartilha linkada no texto do formulário
  'Itaú':     { campos: [] }, // cartilha linkada no texto do formulário
};

const resultado = [];

for (const s of novas) {
  const r = s.responses || s.answers || [];
  const cnpj = (campo(r, 'CNPJ do estabelecimento') || '').replace(/\D/g, '');
  const dadosBase = {
    submission_id: s.id,
    submitted_at: s.submittedAt || s.createdAt,
    razao_social: campo(r, 'Razão Social'),
    cnpj,
    // multi-loja 21/09/2026: CNPJ da unidade (campo novo 'CNPJ desta loja'); submissoes antigas caem no CNPJ do estabelecimento
    cnpj_loja: (campo(r, 'CNPJ desta loja') || '').replace(/\D/g, '') || cnpj,
    nome_responsavel: campo(r, 'Nome do responsável'),
    email: campo(r, 'E-mail'),
    telefone: campo(r, 'Telefone'),
  };

  const adquirentes = campoArray(r, 'Qual adquirente você vai usar no TEF?');
  const bancosPix = campoArray(r, 'Qual banco você vai usar para receber via PIX?');

  // Item resumo — usado para atualizar base_funil_completo e disparar a notificação
  resultado.push({ json: {
    ...dadosBase,
    tipo: 'resumo',
    adquirentes_selecionados: adquirentes.join(', '),
    bancos_pix_selecionados: bancosPix.join(', '),
    nome_software_pdv: campo(r, 'Nome do Software PDV / Automação Comercial'),
  }});

  // Um item por adquirente marcado
  for (const adq of adquirentes) {
    if (adq === 'C6 Pay (mais simples — sem dados necessários)' || adq === 'C6 Pay') continue; // fast path, sem campo
    const spec = TABELA_ADQUIRENTE[adq];
    if (!spec) {
      resultado.push({ json: { ...dadosBase, tipo: 'adquirente_erro', adquirente: adq,
        erro: 'Adquirente não mapeado na tabela de referência — campo pode não ter sido lido corretamente.' }});
      continue;
    }
    const labelAfiliacao = spec.rotuloAfiliacao || 'Número de Afiliação';
    const sufixo = adq === 'Cielo' ? '' : ` (${adq})`;
    resultado.push({ json: {
      ...dadosBase,
      tipo: 'adquirente',
      adquirente: adq,
      pinpad: campo(r, 'Você já tem o equipamento (PinPad)?'),
      numero_afiliacao: spec.afiliacao ? campo(r, `${labelAfiliacao}${sufixo}`) : '',
      numero_logico: spec.logico ? campo(r, `Número Lógico${sufixo}`) : '',
      confirmacao_portal: spec.confirmacaoPortal ? (campoArray(r, 'Confirme quando tiver habilitado a integração').length > 0 ? 'Sim' : 'Não') : '',
      nome_software_pdv: campo(r, 'Nome do Software PDV / Automação Comercial'),
    }});
  }

  // Um item por banco PIX marcado
  for (const banco of bancosPix) {
    const bancoBase = banco.split(' (')[0]; // remove sufixo tipo "(já incluído se..."
    const spec = ESTRUTURA_PIX[bancoBase] || ESTRUTURA_PIX[banco];
    if (!spec) {
      resultado.push({ json: { ...dadosBase, tipo: 'pix_erro', banco,
        erro: 'Banco não mapeado na estrutura de referência.' }});
      continue;
    }
    const item = { ...dadosBase, tipo: 'pix', banco: bancoBase };
    if (spec.campos.includes('client_id')) item.client_id = campoPorId(r, spec.ids?.client_id, 'Client ID');
    if (spec.campos.includes('client_secret')) item.client_secret = campoPorId(r, spec.ids?.client_secret, 'Client Secret');
    if (spec.campos.includes('chave_evp')) item.chave_evp = campoPorId(r, spec.ids?.chave_evp, 'Chave EVP');
    if (spec.campos.includes('tipo_chave')) item.tipo_chave = campo(r, `Tipo de chave Pix (${bancoBase})`);
    if (spec.campos.includes('chave_pix')) item.chave_pix = campo(r, `Qual é a chave Pix (${bancoBase})`);
    resultado.push({ json: item });
  }
}

return resultado;

// multi-loja 21/09/2026: resolve o lead da proposta (lead_id + quantidade_lojas) a partir de base_funil_completo
// item 'resumo' completo vem do Switch (o node Atualizar Resumo devolve so as colunas gravadas)
const resumo = $('Rotear por Tipo').item.json;
const dig = v => String(v || '').replace(/\D/g, '');
const values = ($json.values || []);
const header = values[0] || [];
const rows = values.slice(1).map(r => Object.fromEntries(header.map((h, i) => [h, r[i] !== undefined ? r[i] : ''])));
const cnpjEst = dig(resumo.cnpj);
const email = String(resumo.email || '').trim().toLowerCase();
// Parte 2 (22/09/2026): prioriza o lead_id vindo do campo oculto do Tally (P2_02), depois cnpj, depois e-mail
const leadIdOculto = String(resumo.lead_id_oculto || '').trim();
let lead = leadIdOculto ? (rows.find(r => String(r.lead_id || '').trim() === leadIdOculto) || null) : null;
let resolvidoPor = lead ? 'lead_id' : '';
if (!lead) { lead = rows.find(r => cnpjEst && dig(r.cnpj) === cnpjEst) || null; resolvidoPor = lead ? 'cnpj' : ''; }
if (!lead && email) { lead = rows.find(r => String(r.email || '').trim().toLowerCase() === email) || null; resolvidoPor = lead ? 'email' : ''; }
function cnpjValido(c) {
  c = dig(c); if (c.length !== 14 || /^(\d)\1+$/.test(c)) return false;
  const calc = (base, pesos) => { const s = base.split('').reduce((a, d, i) => a + Number(d) * pesos[i], 0); const r = s % 11; return r < 2 ? 0 : 11 - r; };
  const d1 = calc(c.slice(0, 12), [5,4,3,2,9,8,7,6,5,4,3,2]);
  const d2 = calc(c.slice(0, 12) + d1, [6,5,4,3,2,9,8,7,6,5,4,3,2]);
  return c.slice(12) === `${d1}${d2}`;
}
const cnpjLoja = dig(resumo.cnpj_loja) || cnpjEst;
return { json: {
  ...resumo,
  cnpj_loja: cnpjLoja,
  cnpj_loja_valido: cnpjValido(cnpjLoja),
  lead_encontrado: !!lead,
  lead_resolvido_por: resolvidoPor,
  lead_id: lead ? String(lead.lead_id || '') : '',
  quantidade_lojas: lead ? (Math.max(1, Number(dig(lead.quantidade_lojas)) || 1)) : 1,
  lead_razao_social: lead ? (lead.razao_social || '') : '',
  lead_email: lead ? (lead.email || '') : '',
}};

// multi-loja 21/09/2026: conta lojas distintas ja cadastradas por lead (inclui as submissoes desta rodada, em ordem)
const dig = v => String(v || '').replace(/\D/g, '');
const resolvidos = $('ML_02_resolve_lead').all().map(i => i.json);
const leituras = $input.all();
const porLead = new Map();
const idsJaGravados = new Set();
const out = [];
for (let i = 0; i < leituras.length; i++) {
  const r = resolvidos[i] || {};
  if (i === 0) {
    const values = leituras[0].json.values || [];
    const header = values[0] || [];
    for (const row of values.slice(1)) {
      const o = Object.fromEntries(header.map((h, k) => [h, row[k] !== undefined ? row[k] : '']));
      if (!o.lead_id) continue;
      if (!porLead.has(String(o.lead_id))) porLead.set(String(o.lead_id), new Set());
      if (dig(o.cnpj_loja)) porLead.get(String(o.lead_id)).add(dig(o.cnpj_loja));
      if (o.submission_id) idsJaGravados.add(String(o.submission_id));
    }
  }
  const chave = r.lead_id || ('sem_lead:' + dig(r.cnpj));
  if (!porLead.has(chave)) porLead.set(chave, new Set());
  const jaRegistrada = idsJaGravados.has(String(r.submission_id));
  if (dig(r.cnpj_loja)) porLead.get(chave).add(dig(r.cnpj_loja));
  const cnpjs = [...porLead.get(chave)];
  const esperadas = Math.max(1, Number(r.quantidade_lojas) || 1);
  const preenchidas = cnpjs.length;
  out.push({ json: {
    ...r,
    ja_registrada: jaRegistrada,
    multi_loja: esperadas > 1,
    lojas_esperadas: esperadas,
    lojas_preenchidas: preenchidas,
    lojas_faltantes: Math.max(0, esperadas - preenchidas),
    lojas_completo: preenchidas >= esperadas,
    cnpjs_lista: cnpjs,
    cnpjs_texto: cnpjs.join(', '),
  }, pairedItem: { item: i } });
}
return out;

