// Parte 2 (22/09/2026) - resolucao do lead pelo campo oculto lead_id do Tally, com fallback por e-mail.
// Aditivo: recebe os itens do Normalizar e devolve os mesmos itens com cnpj (matriz), lead_id e cnpj_software_house preenchidos.
// O campo "CNPJ do estabelecimento" deixou de existir no formulario; o cnpj (matriz) passa a vir de base_funil_completo.
const dig = v => String(v || '').replace(/\D/g, '');
const itens = $('Normalizar e Filtrar Novas Submissões (multi-select)').all().map(i => i.json);
const values = ($input.first().json.values || []);
const header = values[0] || [];
const rows = values.slice(1).map(r => Object.fromEntries(header.map((h, i) => [h, r[i] !== undefined ? r[i] : ''])));
// campos ocultos / novos lidos direto da resposta bruta do Tally (sem alterar o Normalizar)
const raw = $('Buscar Submissões do Tally').first().json || {};
const questoes = raw.questions || [];
// campo oculto: no API do Tally a pergunta vem com type 'HIDDEN_FIELDS', title null e fields[].title = 'lead_id';
// a resposta vem como objeto { lead_id: '<valor>' } (validado com submissao real em 22/09/2026)
const idsLeadId = new Set(questoes.filter(q => q.type === 'HIDDEN_FIELDS' || (q.fields || []).some(f => String(f.title || '').trim().toLowerCase() === 'lead_id') || String(q.title || '').trim().toLowerCase() === 'lead_id').map(q => q.id));
const idsSwHouse = new Set(questoes.filter(q => String(q.title || '').trim().toLowerCase() === 'cnpj da software house').map(q => q.id));
const extras = {};
for (const s of (raw.submissions || [])) {
  const resp = s.responses || s.answers || [];
  const pick = ids => {
    const r = resp.find(x => ids.has(x.questionId || (x.field && x.field.id)));
    let v = r ? (r.answer !== undefined ? r.answer : r.value) : '';
    if (v && typeof v === 'object' && !Array.isArray(v)) { v = v.lead_id !== undefined ? v.lead_id : (Object.values(v)[0] ?? ''); }
    return v === null || v === undefined ? '' : String(v);
  };
  extras[s.id] = { lead_id_oculto: pick(idsLeadId).trim(), cnpj_software_house: dig(pick(idsSwHouse)) };
}
return itens.map((it, i) => {
  const ex = extras[it.submission_id] || { lead_id_oculto: '', cnpj_software_house: '' };
  const email = String(it.email || '').trim().toLowerCase();
  let lead = null, por = '';
  if (ex.lead_id_oculto) { lead = rows.find(r => String(r.lead_id || '').trim() === ex.lead_id_oculto) || null; por = lead ? 'lead_id' : ''; }
  if (!lead && dig(it.cnpj)) { lead = rows.find(r => dig(r.cnpj) === dig(it.cnpj)) || null; por = lead ? 'cnpj' : ''; }
  if (!lead && email) { lead = rows.find(r => String(r.email || '').trim().toLowerCase() === email) || null; por = lead ? 'email' : ''; }
  const cnpjMatriz = dig(it.cnpj) || (lead ? dig(lead.cnpj) : '') || dig(it.cnpj_loja);
  return { json: {
    ...it,
    cnpj: cnpjMatriz,
    cnpj_loja: dig(it.cnpj_loja) || cnpjMatriz,
    lead_id: lead ? String(lead.lead_id || '') : ex.lead_id_oculto,
    lead_id_oculto: ex.lead_id_oculto,
    lead_resolvido_por_p2: por,
    cnpj_software_house: ex.cnpj_software_house,
  }, pairedItem: { item: i } };
});
